#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    auto op = [&](int x, int y) {
        assert(x >= 1 && y >= 1 && x + y < n);
        ops.push_back({x, y});
        apply(p, x, y);
    };

    // Place values 1, 2, ..., n-2 into positions 0, 1, ..., n-3
    // After that last two are forced (or need one more op)

    for (int i = 0; i < n - 2; i++) {
        int j = find(p.begin() + i, p.end(), i + 1) - p.begin();
        if (j == i) continue;

        // We want to move p[j] to position i.
        // Step 1: Move it to the suffix (last position)
        if (j != n - 1) {
            // op(j+1, n-1-j): x=j+1, y=n-1-j, x+y=n, need <n. Fails.
            // op(j, n-1-j): swaps [0..j-1] and [j+1..n-1] but leaves p[j] in middle
            // After op(j, n-1-j): [suffix n-1-j][middle=p[j]][prefix j]
            // p[j] goes to position n-1-j. Not helpful directly.

            // Move to end: op with x = j+1, y = n-1-(j+1)+1?  
            // Just move to last: if j < n-1, op(j+1, n-j-2) if n-j-2>=1 i.e. j<n-2
            if (j < n - 2 && j + 1 >= 1) {
                op(j + 1, n - j - 2); // p[j] was at position j, now at end (position n-1) of new array? No: prefix j+1 goes to end, suffix n-j-2 goes to start. p[j] is last of prefix, so goes to position n-1.
                j = n - 1;
            } else if (j == n - 2) {
                // swap to make it n-1: op(n-2, 1): [0..n-3][n-2][n-1] -> [n-1][n-2][0..n-3]. Now p[j]=p[n-2] goes to pos 1.
                op(1, 1); // [last][middle][first] 
                j = find(p.begin() + i, p.end(), i + 1) - p.begin();
                if (j == i) continue;
                if (j < n - 2 && j + 1 >= 1) { op(j + 1, n - j - 2); j = n - 1; }
            }
        }
        j = find(p.begin() + i, p.end(), i + 1) - p.begin();
        if (j == i) continue;
        // Now element is at position j. Bring to position i.
        if (j == n - 1 && i + 1 <= n - 2) {
            op(i, n - 1 - i); // brings last n-1-i elements to front; element at n-1 goes to position n-1-i. Hmm, let me think: suffix=n-1-i, it goes to front. Element at n-1 is last of suffix, goes to position n-1-i-1? No: suffix is p[i+1..n-1], size n-1-i. It becomes positions 0..n-2-i. p[n-1] -> position n-2-i. Not i.
            // Actually: op(i, n-1-i): prefix [0..i-1] size i, suffix [i+1..n-1] size n-1-i. But wait x+y=n-1 < n. Middle is p[i], size 1.
            // Result: [suffix][p[i]][prefix] = [p[i+1]..p[n-1], p[i], p[0]..p[i-1]]
            // p[n-1] goes to position n-1-i-1 = n-2-i. Not what we want if i>0.
            // Let's just do: if element is at n-1, op(i, n-1-i) won't place it at i.
            // Better: if i>=1, op(i, 1): suffix=1 (just p[n-1]), goes to front. p[n-1] goes to position 0. Then we need to bring it from 0 to i... not helpful.
            // Actually op(i,1) if i>=1: [p[n-1], p[i]..p[n-2], p[0]..p[i-1]]. Element now at 0. Then op(1, n-1-i-1)? Hmm getting complicated. Let me just use: bring to position 0 first (op with y including it), then rotate to position i.
        }
        // Restart: find again
        j = find(p.begin() + i, p.end(), i + 1) - p.begin();
        if (j == i) continue;
        if (i == 0) {
            // bring p[j] to position 0: op(j, n-1-j) if j>=1 && n-1-j>=1 && j+n-1-j<n (always true since middle=1)
            if (j >= 1 && n - 1 - j >= 1) op(j, n - 1 - j);
            // now check
            j = find(p.begin(), p.end(), i + 1) - p.begin();
            if (j != 0 && j == n - 1 && n >= 3) { op(1, n - 2); j = find(p.begin(), p.end(), i + 1) - p.begin(); }
        } else {
            // bring to pos 0 then to pos i
            if (j >= 1 && n - 1 - j >= 1) { op(j, n - 1 - j); j = 0; }
            j = find(p.begin() + i, p.end(), i + 1) - p.begin();
            if (j == 0 && i >= 2) { op(1, n - 1 - i); j = find(p.begin() + i, p.end(), i + 1) - p.begin(); }
            if (j == 0 && i == 1 && n >= 3) { op(1, n - 2); j = find(p.begin() + i, p.end(), i + 1) - p.begin(); }
        }
        if ((int)ops.size() > 4 * n) break;
    }

    printf("%d\n", (int)ops.size());
    for (auto& [a, b] : ops) printf("%d %d\n", a, b);
}
